/**
 * A refreshed conclusion's `artifacts` names only the paths that refresh delivered, so the
 * prior paths must be recovered from `check.artifacts` as well when deciding whether this
 * advance touched an artifact the principal already knew about.
 */
const knownArtifacts = new Set([
  ...latest.artifacts,
  ...(latest.check.artifacts ?? []).map((state) => state.path),
]);
const touched = changed.filter((path) => knownArtifacts.has(path));
const preparedAdvance = isPreparedAdvance(repository, head);
if (touched.length === 0 && !preparedAdvance) {
  return Object.freeze({ recorded: false, detail: "the direct commit touches no artifact named by the DELIVER conclusion" });
}
const addedPaths = changed.filter((path) => !knownArtifacts.has(path));
const paths = [...new Set([...knownArtifacts, ...changed])];
const freshStates = artifactStates(repository, head, paths);
if (freshStates.length === 0) return Object.freeze({ recorded: false, detail: "no named artifact is a readable blob at HEAD" });
const states = mergeArtifactStates(latest.check.artifacts, freshStates, changed);
/**
 * Only the moved/added paths are THIS delivery. Prior artifacts remain in `check.artifacts`
 * with their original commit and a carried label, so the next worker can still see what was
 * delivered earlier without treating all of it as newly recorded here.
 */
const deliveredPaths = changed.filter((path) => states.some((state) => state.path === path));
if (deliveredPaths.length === 0) {
  return Object.freeze({ recorded: false, detail: "the direct advance names no readable delivered artifact" });
}
if (sameArtifacts(latest.check.artifacts, states)) {
  return Object.freeze({ recorded: false, detail: "the DELIVER conclusion already covers these exact bytes", conclusionId: latest.conclusionId });
}

